const TODAY = plainDate(new Date(), "America/Los_Angeles");
const d = (offset: number) => addDays(TODAY, offset);

async function wipeDemoOrg(): Promise<void> {
  const db = getDb();
  const [org] = await db.select().from(orgs).where(eq(orgs.name, ORG_NAME));
  if (!org) return;

  const vendorRows = await db.select({ id: vendors.id }).from(vendors).where(eq(vendors.orgId, org.id));
  const vendorIds = vendorRows.map((v) => v.id);
  const certRows = vendorIds.length
    ? await db.select({ id: certificates.id }).from(certificates).where(inArray(certificates.vendorId, vendorIds))
    : [];
  const certIds = certRows.map((c) => c.id);
  const engagementRows = vendorIds.length
    ? await db.select({ id: engagements.id }).from(engagements).where(inArray(engagements.vendorId, vendorIds))
    : [];
  const engagementIds = engagementRows.map((e) => e.id);

  if (engagementIds.length) {
    await db.delete(chases).where(inArray(chases.engagementId, engagementIds));
    await db.delete(evaluations).where(inArray(evaluations.engagementId, engagementIds));
  }
  if (certIds.length) {
    await db.delete(coverages).where(inArray(coverages.certificateId, certIds));
    await db.delete(certificateBlobs).where(inArray(certificateBlobs.certificateId, certIds));
  }
  if (engagementIds.length) await db.delete(engagements).where(inArray(engagements.id, engagementIds));
  if (certIds.length) await db.delete(certificates).where(inArray(certificates.id, certIds));
  await db.delete(binderExports).where(eq(binderExports.orgId, org.id));
  await db.delete(auditLog).where(eq(auditLog.orgId, org.id));
  await db.delete(requirementTemplates).where(eq(requirementTemplates.orgId, org.id));
  if (vendorIds.length) await db.delete(vendors).where(inArray(vendors.id, vendorIds));
  await db.delete(properties).where(eq(properties.orgId, org.id));
  await db.delete(users).where(eq(users.orgId, org.id));
  await db.delete(orgs).where(eq(orgs.id, org.id));
}

interface VendorSpec {
  name: string;
  trade: string;
  contactName: string;
  contactEmail: string;
  agentName: string;
  agentEmail: string;
  phone: string;
  notes?: string;
  properties: string[];
  template: string;
  /** How this vendor's certificate is meant to land. */
  certificate:
    | { kind: "none" }
    | { kind: "letter" } // a PDF that is not a certificate: the failed-parse case
    | { kind: "acord"; spec: SampleAcord };
}

function acord(over: Partial<SampleAcord>): SampleAcord {
  return compliantSample({ holder: ORG_NAME, ...over });
}

