/** A one-page cover letter: the PDF the failed-parse vendor actually sent. */
async function coverLetterPdf(vendorName: string): Promise<Uint8Array> {
  const { PDFDocument, StandardFonts, rgb } = await import("pdf-lib");
  const doc = await PDFDocument.create();
  const page = doc.addPage([612, 792]);
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const bold = await doc.embedFont(StandardFonts.HelveticaBold);
  const ink = rgb(0.12, 0.14, 0.13);
  let y = 720;
  const put = (text: string, size = 11, f = font) => {
    page.drawText(text, { x: 56, y, size, font: f, color: ink });
    y -= size + 8;
  };
  put(vendorName, 14, bold);
  put("1180 SE Cedar St, Portland, OR 97214");
  y -= 12;
  put(`${ORG_NAME} — Compliance`, 11, bold);
  y -= 12;
  put("Re: insurance documents for the Cedar & 12th renovation");
  y -= 8;
  put("Hello,");
  put("Please find our W-9 and the signed subcontract attached. Our agent is");
  put("preparing the certificate of insurance and will send it directly to you");
  put("this week.");
  y -= 8;
  put("Regards,");
  put("Ruben Vega");
  return doc.save({ useObjectStreams: false });
}

async function main(): Promise<void> {
  const db = getDb();

  const otherOrgs = await db.select({ id: orgs.id, name: orgs.name }).from(orgs);
  const foreign = otherOrgs.filter((o) => o.name !== ORG_NAME);
  if (foreign.length) {
    console.error(
      `Refusing to seed: this database already has ${foreign.length} other org(s) (${foreign
        .map((o) => o.name)
        .join(", ")}). Seed into an empty database.`,
    );
    process.exitCode = 1;
    return;
  }

  await wipeDemoOrg();

  const [org] = await db
    .insert(orgs)
    .values({
      name: ORG_NAME,
      kind: "property_mgmt",
      plan: "trial",
      trialEndsAt: new Date(Date.now() + 11 * 86_400_000),
      timezone: "America/Los_Angeles",
      settings: {
        holderName: `${ORG_NAME} LLC`,
        chaseOffsets: [30, 14, 7, 1],
        tone: "plain",
        hookKey: `hk_${randomBytes(16).toString("hex")}`,
      },
    })
    .returning();

  const passwordHash = await hashPassword(DEMO_PASSWORD);
  await db.insert(users).values([
    {
      orgId: org.id,
      email: "dana@harborridge.example",
      name: "Dana Whitlock",
      role: "admin",
      passwordHash,
    },
    {
      orgId: org.id,
      email: "sam@harborridge.example",
      name: "Sam Iyer",
      role: "coordinator",
      passwordHash,
    },
  ]);

  const propertyRows = await db
    .insert(properties)
    .values(PROPERTIES.map((p) => ({ ...p, orgId: org.id })))
    .returning();
  const propertyByName = new Map(propertyRows.map((p) => [p.name, p]));

  const templateRows = await db
    .insert(requirementTemplates)
    .values(DEFAULT_TEMPLATES.map((t) => ({ ...t, orgId: org.id })))
    .returning();
  const templateByName = new Map(templateRows.map((t) => [t.name, t]));
  await db
    .update(orgs)
    .set({
      settings: { ...org.settings, defaultTemplateId: templateByName.get("Standard vendor")!.id },
    })
    .where(eq(orgs.id, org.id));

  for (const spec of VENDORS) {
    const [vendor] = await db
      .insert(vendors)
      .values({
        orgId: org.id,
        name: spec.name,
        trade: spec.trade,
        contactName: spec.contactName,
        contactEmail: spec.contactEmail,
        agentName: spec.agentName,
        agentEmail: spec.agentEmail,
        phone: spec.phone,
        notes: spec.notes ?? null,
      })
      .returning();
    await issueUploadToken(vendor.id);

    const template = templateByName.get(spec.template) ?? templateRows[0];
    for (const propertyName of spec.properties) {
      const property = propertyByName.get(propertyName);
      if (!property) continue;
      await db.insert(engagements).values({
        vendorId: vendor.id,
        propertyId: property.id,
        requirementTemplateId: template.id,
        startsOn: d(-365),
        status: "active",
      });
    }

    if (spec.certificate.kind === "none") continue;

    const bytes =
      spec.certificate.kind === "letter"
        ? await coverLetterPdf(spec.name)
        : await buildSampleAcordPdf(spec.certificate.spec);

    const intake = await intakeCertificate({
      orgId: org.id,
      vendorId: vendor.id,
      bytes,
      source: spec.certificate.kind === "letter" ? "inbound" : "portal",
      actor: `${spec.contactName} <${spec.contactEmail}> (upload portal)`,
      filename: `${spec.name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-coi.pdf`,
    });
    const outcome = await parseCertificate(intake.certificateId);
    console.log(`  ${spec.name}: ${outcome.status}${outcome.error ? ` — ${outcome.error}` : ""}`);
  }

  const [refreshed] = await db.select().from(orgs).where(eq(orgs.id, org.id));
  const persisted = await persistEvaluations(refreshed);
  console.log(`  ${persisted.written} verdicts recorded`);

  // One chase pass, so the timelines have history. DRY_RUN keeps it off the wire.
  const tick = await runTickForOrg(refreshed);
  console.log(
    `  chases: ${tick.chasesSent} sent, ${tick.chasesSkipped} skipped, ${tick.chasesFailed} failed`,
  );

  console.log(`\nSeeded ${ORG_NAME}.`);
  console.log(`  sign in: dana@harborridge.example / ${DEMO_PASSWORD}`);
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(() => closeDb());
